// vllmCatalogJSON is every vllm serve flag as vLLM's own parser describes it at the pinned
// version: help text, type, default, choices and Field limits. It is
// generated by tools/vllm-catalog/dump.py (`just vllm-catalog`), never edited by hand.
//
//go:embed vllm_catalog.json
var vllmCatalogJSON []byte

// vllmCatalogFile is the generated file's shape; servtuner knobs turns it into a spec.KnobCatalog.
type vllmCatalogFile struct {
	VLLMVersion string            `json:"vllm_version"`
	VLLMCommit  string            `json:"vllm_commit"`
	Flags       []vllmCatalogFlag `json:"flags"`
}

type vllmCatalogFlag struct {
	Flag          string           `json:"flag"`
	Aliases       []string         `json:"aliases"`
	NegativeFlags []string         `json:"negative_flags"`
	Dest          string           `json:"dest"`
	Group         string           `json:"group"`
	Kind          spec.KnobKind    `json:"kind"`
	Default       any              `json:"default"`
	Choices       []any            `json:"choices"`
	Suggestions   []string         `json:"suggestions"`
	Help          string           `json:"help"`
	Limits        *spec.KnobLimits `json:"limits"`
}

var readVLLMCatalog = sync.OnceValues(func() (vllmCatalogFile, error) {
	var catalog vllmCatalogFile
	if err := json.Unmarshal(vllmCatalogJSON, &catalog); err != nil {
		return vllmCatalogFile{}, fmt.Errorf("read the embedded vLLM flag catalog: %w", err)
	}
	return catalog, nil
})

