// acronyms keep their case when a field name is humanized.
var acronyms = map[string]string{
	"api": "API", "cpu": "CPU", "gpu": "GPU", "kv": "KV", "lora": "LoRA", "moe": "MoE", "dp": "DP",
	"tp": "TP", "pp": "PP", "ep": "EP", "eplb": "EPLB", "len": "length", "num": "number of",
	"url": "URL", "ssl": "SSL", "tls": "TLS", "http": "HTTP", "json": "JSON", "id": "ID",
	"mm": "multimodal", "cuda": "CUDA", "numa": "NUMA", "dbo": "DBO", "fp8": "FP8", "max": "max",
}

// humanizeField labels a field vLLM names in snake case: "max_num_partial_prefills" is
// "Max number of partial prefills".
func humanizeField(field string) string {
	words := strings.Split(field, "_")
	for i, word := range words {
		if replacement, known := acronyms[word]; known {
			words[i] = replacement
		}
	}
	label := strings.Join(words, " ")
	return strings.ToUpper(label[:1]) + label[1:]
}

// servtunerOwnedFields are the vLLM fields the deployer sets itself or that would break how servtuner
// serves and reaches the model, so they are never knobs: the model and its name, where and how it
// listens (host, port, socket, TLS, root path, gRPC, headless), the model cache and a config
// file. The api's SERVTUNER_OWNED_FLAGS keeps the same flags out of a target's base flags.
var servtunerOwnedFields = map[string]bool{
	"model": true, "served_model_name": true, "config": true, "download_dir": true,
	"host": true, "port": true, "uds": true, "root_path": true, "grpc": true, "grpc_port": true,
	"headless": true, "ssl_keyfile": true, "ssl_certfile": true, "ssl_ca_certs": true,
	"ssl_cert_reqs": true, "ssl_ciphers": true, "enable_ssl_refresh": true,
}

// rangeTunedKnobs are the knobs the tuning advisors (vLLM's V1 to V5, SGLang's S2 and S3) move and
// the coordinate step varies, so a search space may give them as bounds (servtuner propose).
var rangeTunedKnobs = map[string]bool{
	KnobVLLMMaxNumSeqs:           true,
	KnobVLLMMaxNumBatchedTokens:  true,
	KnobVLLMMaxModelLen:          true,
	KnobSGLangMaxRunningRequests: true,
	KnobSGLangChunkedPrefillSize: true,
	KnobSGLangContextLength:      true,
}

// IsRangeTunedKnob reports whether a search space may give the knob as min and max.
func IsRangeTunedKnob(name string) bool { return rangeTunedKnobs[name] }

// IsWholeNumberKnob reports whether the server parses the knob as a whole number (an integer or a
// size), from its catalog kind (vLLM's or SGLang's) or, for a vLLM knob without a flag, its table kind.
func IsWholeNumberKnob(name string) bool {
	if kind, listed := catalogKindsByName()[name]; listed {
		return kind == spec.KnobKindInteger || kind == spec.KnobKindSize
	}
	if flag, listed := sglangKnobsByName()[name]; listed {
		return flag.Kind == spec.KnobKindInteger || flag.Kind == spec.KnobKindSize
	}
	for _, field := range compilationConfigKnobs {
		if field.knob == name {
			return field.kind == knobInteger || field.kind == knobSize
		}
	}
	return false
}

var catalogKindsByName = sync.OnceValue(func() map[string]spec.KnobKind {
	file, err := readVLLMCatalog()
	if err != nil {
		panic(err) // embedded and tested: see catalogVLLMFlags
	}
	kinds := map[string]spec.KnobKind{}
	for _, flag := range file.Flags {
		kinds[vllmPrefix+flag.Dest] = flag.Kind
	}
	return kinds
})

// knobKinds maps the catalog's kinds to how bench reads and spells them. A JSON or list flag has no
// single knob value, so it is not a knob (a target's base flags can still set it).
var knobKinds = map[spec.KnobKind]knobKind{
	spec.KnobKindInteger: knobInteger,
	spec.KnobKindNumber:  knobNumber,
	spec.KnobKindSize:    knobSize,
	spec.KnobKindBoolean: knobBoolean,
	spec.KnobKindSwitch:  knobSwitch,
	spec.KnobKindChoice:  knobText,
	spec.KnobKindText:    knobText,
}

// isCatalogKnob reports whether a catalog flag is a knob: one value, and not servtuner's to set.
func isCatalogKnob(flag vllmCatalogFlag) bool {
	_, single := knobKinds[flag.Kind]
	return single && !servtunerOwnedFields[flag.Dest]
}

// catalogVLLMFlags are the knob table rows for every catalog knob without a built-in row. The
// catalog is embedded and checked by its test, so a broken one stops bench at start-up.
func catalogVLLMFlags() []vllmFlag {
	file, err := readVLLMCatalog()
	if err != nil {
		panic(err)
	}
	builtIn := map[string]bool{}
	for _, flag := range builtInVLLMFlags {
		builtIn[flag.knob] = true
	}
	for _, field := range compilationConfigKnobs {
		builtIn[field.knob] = true
	}
	var flags []vllmFlag
	for _, flag := range file.Flags {
		name := vllmPrefix + flag.Dest
		if builtIn[name] || !isCatalogKnob(flag) {
			continue
		}
		flags = append(flags, vllmFlag{name, knobKinds[flag.Kind], append([]string{flag.Flag}, flag.Aliases...)})
	}
	return flags
}

// KnobCatalog describes every knob: each vLLM flag that is one (isCatalogKnob), labelled when it
// is built in and named from its field otherwise, then the CompilationConfig knobs that have no
// flag of their own and no argparse help.
func KnobCatalog() (spec.KnobCatalog, error) {
	file, err := readVLLMCatalog()
	if err != nil {
		return spec.KnobCatalog{}, err
	}
	knobs := make([]spec.KnobDescription, 0, len(file.Flags)+len(compilationConfigKnobs))
	for _, flag := range file.Flags {
		name := vllmPrefix + flag.Dest
		if !IsVLLMKnob(name) {
			continue
		}
		label, builtIn := knobLabels[name]
		if !builtIn {
			label = humanizeField(flag.Dest)
		}
		description := spec.KnobDescription{
			Name:          name,
			Label:         label,
			Flag:          flag.Flag,
			Aliases:       flag.Aliases,
			NegativeFlags: flag.NegativeFlags,
			Group:         flag.Group,
			Kind:          flag.Kind,
			Default:       flag.Default,
			Help:          flag.Help,
			Limits:        flag.Limits,
			BuiltIn:       builtIn,
			TunedAsRange:  IsRangeTunedKnob(name),
		}
		if flag.Choices != nil {
			choices := spec.KnobDescriptionChoices(flag.Choices)
			description.Choices = &choices
		}
		if flag.Suggestions != nil {
			suggestions := spec.KnobDescriptionSuggestions(flag.Suggestions)
			description.Suggestions = &suggestions
		}
		knobs = append(knobs, description)
	}
	listed := map[string]bool{}
	for _, knob := range knobs {
		listed[knob.Name] = true
	}
	for _, field := range compilationConfigKnobs {
		if listed[field.knob] {
			continue // it has a flag of its own too (--max-cudagraph-capture-size)
		}
		knobs = append(knobs, spec.KnobDescription{
			Name:    field.knob,
			Label:   knobLabels[field.knob],
			Group:   "CompilationConfig",
			Kind:    catalogKind(field.kind),
			Help:    "Set through --compilation-config (" + field.field + ").",
			BuiltIn: true,
		})
	}
	other := []string{}
	for _, flag := range file.Flags {
		if !IsVLLMKnob(vllmPrefix + flag.Dest) {
			other = append(other, flag.Flag)
			other = append(other, flag.Aliases...)
			other = append(other, flag.NegativeFlags...)
		}
	}
	sort.Strings(other)
	return spec.KnobCatalog{Server: spec.KnobCatalogServerVllm, Version: file.VLLMVersion, Commit: file.VLLMCommit, Knobs: knobs, OtherFlags: other}, nil
}

// catalogKind is the catalog's name for a knob table kind.
func catalogKind(kind knobKind) spec.KnobKind {
	switch kind {
	case knobNumber:
		return spec.KnobKindNumber
	case knobInteger:
		return spec.KnobKindInteger
	case knobSize:
		return spec.KnobKindSize
	case knobBoolean:
		return spec.KnobKindBoolean
	case knobSwitch:
		return spec.KnobKindSwitch
	default:
		return spec.KnobKindText
	}
}
